using System.Text.Json;
using OcctSharp.ConstructionWorkspaces;
using OcctSharp.ExtremaResults;
using OcctSharp.MeshProximity;
using OcctSharp.DocumentProjections;
using OcctSharp.LocalStepExports;
namespace OcctSharp.Tests.Shared;
internal static class BatchBQWholeRoundWorkflow {
 internal static void Require(bool condition,string detail){if(!condition)throw new InvalidOperationException("BQ: "+detail);}
 internal static void Run(){
  using var builtA=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,ConstructionFrame.World,0,4);using var builtB=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,new(new(2,-2,2),new(0,0,1),new(0,1,0)),0,4);using var edgeA=builtA.CopyShape();using var edgeB=builtB.CopyShape();using var curveA=FiniteExtremaGeometry.CopyCurve(edgeA);using var curveB=FiniteExtremaGeometry.CopyCurve(edgeB);using var extrema=FiniteExtrema.CurveCurve(curveA,new(0,4),curveB,new(0,4));Require(extrema.IsDone&&!extrema.IsParallel&&extrema.Rows.Count==1&&extrema.Rows[0].Points is not null,"real BL -> BM coupled extremum");var row=extrema.Rows[0];var pair=row.Points!;double distance=Math.Sqrt(row.SquareDistance);Require(Math.Abs(distance-2)<1e-6,"analytic finite-domain distance reference");curveA.Dispose();curveB.Dispose();edgeA.Dispose();edgeB.Dispose();builtA.Dispose();builtB.Dispose();Require(BatchBMFiniteExtremaWorkflow.Distance(extrema.EvaluateSource(0,pair.First.FirstParameter),pair.First.Point)<1e-6&&BatchBMFiniteExtremaWorkflow.Distance(extrema.EvaluateSource(1,pair.Second.FirstParameter),pair.Second.Point)<1e-6,"BM source closure and point/parameter coupling");
  using var first=BatchBOMeshProximityWorkflow.Face();using var second=BatchBOMeshProximityWorkflow.Face(distance,4);using var proximity=MeshProximityComputations.Compute(first,second,new(Mode:MeshProximityMode.LayerThickness));Require(proximity.WasPerformed&&proximity.IsDone&&proximity.LayerThickness is {} thickness&&Math.Abs(thickness-distance)<1e-6&&proximity.Reference is not null&&proximity.IsApproximate&&proximity.CertifiedGeometricErrorBound is null,"BL -> controlled mesh -> BO finite analytic comparison");first.Dispose();second.Dispose();using var retainedFace=proximity.CopyFace(0,0);Require(retainedFace.IsValid&&MeshTopology.SnapshotExisting(retainedFace).Mesh.Triangles.Count==2,"BO independent copied mesh lifetime");var names=BatchBNBoundedTextWorkflow.Names();
  string directory=Path.Combine(Path.GetTempPath(),"OcctSharp.BQ."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{using var source=BatchBPLocalExportWorkflow.Source(directory,proximity.LayerThickness!.Value);using var context=DocumentProjectionContext.Bind(source.Document);var root=context.GetLabel(source.Diagnostics.FreeRoots.Single(x=>x.Name==names[0]).Entry);var written=LocalStepAssemblyExport.Export(context,[root],Path.Combine(directory,"round-output"));source.Dispose();BatchBPLocalExportWorkflow.Verify(written);written.Validate();double exportedHeight=0;using(var readback=written.OpenForReadback()){using var rebuilt=readback.Transfer(readback.Roots.Select(x=>x.Id));using var assembled=rebuilt.CopyFreeRoot(1);var box=assembled.GetBoundingBox();exportedHeight=box.SizeZ;Require(Math.Abs(exportedHeight-proximity.LayerThickness!.Value)<1e-5,"actual exported geometry retains measured BO height");}string evidence=Environment.GetEnvironmentVariable("OCCTSHARP_BATCH_BQ_EVIDENCE")??Path.Combine(directory,"visible-evidence");Directory.CreateDirectory(evidence);foreach(var file in written.Files)File.Copy(Path.Combine(written.DirectoryPath,file.FileName),Path.Combine(evidence,file.FileName),true);string metrics=JsonSerializer.Serialize(new{finiteSquareDistance=row.SquareDistance,exportedHeight,finiteRows=extrema.Rows.Count,finiteEndpointCombinations=extrema.EndpointCombinations.Count,layerThickness=proximity.LayerThickness,layerNativeDone=proximity.IsDone,approximate=true,certifiedBound=(double?)null,firstTriangles=proximity.FirstTriangles,secondTriangles=proximity.SecondTriangles,unicodeNames=names,exportedFiles=written.Files});var values=names.Concat([metrics]).Concat(written.Files.Select(x=>x.FileName+":"+x.Sha256)).ToArray();BatchBQRawAssemblyViewer.Run(Path.Combine(written.DirectoryPath,written.MainFile),evidence,values);File.WriteAllText(Path.Combine(evidence,"chain-result.json"),JsonSerializer.Serialize(new{state="PASS",newBlGeometry=true,bmInputClosed=true,bmCoupledPointResidual=true,boInputClosed=true,exportedHeightVerified=true,exportedHeight,finiteSquareDistance=row.SquareDistance,layerThickness=proximity.LayerThickness,unicodeNames=names,newBpFiles=written.Files,mainFile=written.MainFile,xbfMetadataValues=values,hwndDxgi="visible-result.json",publicConsumer=
#if DIRECT_MODULE_CONSUMER
   "module"
#else
   "facade"
#endif
  }));}
  finally{Directory.Delete(directory,true);}
 }
}
